import{describe,it,expect,beforeEach,vi}from"vitest";describe("Bharat AI Guide Voice Input & Multilingual Support",()=>{beforeEach(()=>{document.body.innerHTML='\n      <button class="fab-guide" id="fab-guide"></button>\n      <div class="guide-chat-window" id="guide-chat-window">\n        <button id="btn-close-chat"></button>\n        <div id="chat-messages"></div>\n        <div class="chat-input-area">\n          <select id="chat-lang-select" class="chat-lang-select">\n            <option value="en-IN">English</option>\n            <option value="hi-IN">Hindi</option>\n            <option value="ta-IN">Tamil</option>\n            <option value="bn-IN">Bengali</option>\n            <option value="mr-IN">Marathi</option>\n            <option value="te-IN">Telugu</option>\n          </select>\n          <input type="text" id="chat-input" placeholder="Type or speak...">\n          <button id="btn-mic" class="btn-mic">🎤</button>\n          <button id="btn-send-msg" class="btn-send">➤</button>\n        </div>\n      </div>\n    ',delete window.SpeechRecognition,delete window.webkitSpeechRecognition}),it("contains regional language options in language selector dropdown",()=>{const t=document.getElementById("chat-lang-select");expect(t).not.toBeNull();const e=Array.from(t.options).map(t=>t.value);expect(e).toEqual(["en-IN","hi-IN","ta-IN","bn-IN","mr-IN","te-IN"])}),it("displays fallback message when Web Speech API is not supported",async()=>{const{initBharatGuide:t}=await(import("../../frontend/js-modules/initBharatGuide.js"));t();document.getElementById("btn-mic").click();const e=document.getElementById("chat-messages");expect(e.textContent).toContain("Voice recognition is not supported in your browser")}),it("starts recognition with selected language when Web Speech API is available",async()=>{let t=!1,e="";window.SpeechRecognition=class{constructor(){this.lang="en-IN"}start(){t=!0,e=this.lang,"function"==typeof this.onstart&&this.onstart()}stop(){t=!1,"function"==typeof this.onend&&this.onend()}};const{initBharatGuide:n}=await(import("../../frontend/js-modules/initBharatGuide.js"));n();document.getElementById("chat-lang-select").value="hi-IN";const i=document.getElementById("btn-mic");i.click(),expect(t).toBe(!0),expect(e).toBe("hi-IN"),expect(i.classList.contains("listening")).toBe(!0)})});